fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Convert 1-based index k to zero-based index
    let remove_index = k - 1;

    // Pre-allocate new vector for efficiency, length will be one less
    let mut new_list = Vec::with_capacity(list.len() - 1);

    // Push elements before the remove_index
    for i in 0..remove_index {
        new_list.push(list[i]);
    }

    // Push elements after the remove_index
    for i in remove_index + 1..list.len() {
        new_list.push(list[i]);
    }

    new_list
}